transforms.code:
result = None
selected = value.get('selectedPens') if hasattr(value, 'get') else None
hours = value.get('hours') if hasattr(value, 'get') else 1
if selected is None:
	return result
if isinstance(selected, (str, unicode)):
	selected = [selected] if selected else []
try:
	hours = int(hours) if hours is not None else 1
except:
	hours = 1
if hours <= 0:
	hours = 1

paths = []
aliases = []
seen = set()
for item in selected:
	path = str(item or '').strip()
	if not path or path in seen:
		continue
	seen.add(path)
	paths.append(path)
	leaf = path.rsplit('/', 1)[-1]
	parts = path.split('/')
	if len(parts) >= 3 and leaf.upper() == 'VALUE' and parts[-2].upper() == 'VALUE':
		alias = parts[-3]
	elif len(parts) >= 2 and leaf.upper() == 'VALUE':
		alias = parts[-2]
	else:
		alias = (parts[-2] + ' ' + leaf) if len(parts) >= 2 else leaf  # pax-bindings: PAX member
	aliases.append(alias)

if not paths:
	return result

end = system.date.now()
start = system.date.addHours(end, -hours)
try:
	result = system.tag.queryTagHistory(
		paths=paths,
		startDate=start,
		endDate=end,
		returnSize=120,
		aggregationMode='Average',
		returnFormat='Tall',
		columnNames=aliases
	)
except:
	result = None
return result

result = []
tag_path = value.get('tagPath', '') if hasattr(value, 'get') else ''
hiddenTagsInput = value.get('hiddenTags', '') if hasattr(value, 'get') else ''
if tag_path:
	tag_path = str(tag_path).rstrip('/')
if not tag_path:
	return result

hidden_set = set()
try:
	text = str(hiddenTagsInput or '')
	if text:
		text = text.replace(';', ',')
		for item in text.split(','):
			item = item.strip()
			if item:
				hidden_set.add(item)
except Exception:
	pass

def isHidden(fullPath):
	if not hidden_set:
		return False
	stripped = fullPath.split(']', 1)[-1] if ']' in fullPath else fullPath
	norm = stripped.replace(chr(92), '/')
	if fullPath in hidden_set or stripped in hidden_set or norm in hidden_set:
		return True
	norm_slash = '/' + norm.strip('/') + '/'
	for h in hidden_set:
		hh = str(h).replace(chr(92), '/')
		if hh.endswith('/'):
			seg = hh.strip('/')
			if not seg:
				continue
			if ('/' + seg + '/') in norm_slash:
				return True
			if norm.strip('/') == seg or norm.strip('/').startswith(seg + '/'):
				return True
		else:
			if norm.endswith('/' + hh) or norm.split('/')[-1] == hh:
				return True
	return False

candidates = []
paxKey = shared.Pax.part(tag_path)
try:
	browse = system.tag.browse(path=tag_path, filter={'recursive': True}).getResults()
except:
	browse = []
for entry in browse:
	try:
		tag_type = str(entry['tagType'])
	except:
		tag_type = ''
	if tag_type in ('Folder', 'UdtType', 'UdtInstance', 'Property'):
		continue
	full_path = str(entry['fullPath'])
	if '.' in full_path.rsplit('/', 1)[-1]:
		continue
	if isHidden(full_path):
		continue
	if paxKey and full_path.rsplit('/', 1)[-1] == 'Value':
		continue   # pax-bindings: a PLC-mapped device trends its historized PlantPAx members
	candidates.append(full_path)

if not candidates:
	return result

all_paths = []
for p in candidates:
	all_paths.append(p + '.Enabled')
	all_paths.append(p + '.HistoryEnabled')
	all_paths.append(p + '.DataType')
try:
	all_values = system.tag.readBlocking(all_paths)
except:
	return result

for i, full_path in enumerate(candidates):
	enabled_qv = all_values[i * 3]
	he_qv = all_values[i * 3 + 1]
	dt_qv = all_values[i * 3 + 2]
	try:
		if not enabled_qv.value:
			continue
	except:
		continue
	try:
		if not he_qv.value:
			continue
	except:
		continue
	try:
		dt_raw = dt_qv.value if dt_qv is not None else ''
		if hasattr(dt_raw, 'name'):
			dt = str(dt_raw.name).lower()
		else:
			dt = str(dt_raw).lower()
		if '.' in dt:
			dt = dt.rsplit('.', 1)[-1]
	except:
		dt = ''
	if 'string' in dt or 'date' in dt or 'bool' in dt:
		continue
	parts = full_path.split('/')
	leaf_name = parts[-1] if parts else full_path
	if len(parts) >= 2 and leaf_name.upper() == 'VALUE':
		alias = parts[-2]
		owner = full_path.rsplit('/', 1)[0]
	else:
		alias = (parts[-2] + ' ' + leaf_name) if paxKey and len(parts) >= 2 else leaf_name  # pax-bindings
		owner = full_path
	result.append({'label': alias, 'value': full_path, 'owner': owner})

# Plain-English labels: member metadata shortDescription -> longDescription -> member name.
# Base-type descriptions inherited from _Root/* say nothing about the member.
generic = ('analog', 'digital', 'multistate', 'string', 'value', 'document')

def describe(md):
	if md is None:
		return ''
	try:
		md = system.util.jsonDecode(str(md))
	except:
		return ''
	if not hasattr(md, 'get'):
		return ''
	for key in ('shortDescription', 'longDescription'):
		text = str(md.get(key) or '').strip()
		if text and text.lower() not in generic:
			return text
	return ''

def title(text):
	return ' '.join([w[:1].upper() + w[1:] if w.islower() else w for w in text.split(' ')])

try:
	mds = system.tag.readBlocking([r['owner'] + '.metadata' for r in result] +
	                              [r['value'] + '.metadata' for r in result])
except:
	mds = []
n = len(result)
for i, r in enumerate(result):
	text = ''
	if len(mds) == 2 * n:
		text = describe(mds[i].value) or describe(mds[n + i].value)
	if text:
		r['label'] = title(text)
counts = {}
for r in result:
	counts[r['label']] = counts.get(r['label'], 0) + 1
for r in result:
	alias = r.pop('owner').rsplit('/', 1)[-1]
	if counts[r['label']] > 1 and r['label'] != alias:
		r['label'] = '%s (%s)' % (r['label'], alias)
# Default pens outside the device folder (e.g. a tank's pumps pressure sensor)
have = set(r['value'] for r in result)
for extra in (value.get('defaultPens') or []):
	extra = str(extra)
	if extra in have:
		continue
	parts = extra.split('/')
	name = parts[-3] if len(parts) >= 3 and parts[-2].upper() == 'VALUE' else parts[-2]
	result.append({'label': name, 'value': extra})
result.sort(key=lambda r: r['label'].lower())
return result

