self.view.custom.selectedPens = None if n == 0 else v

transforms.code:
selected = value.get('selectedPens') or []
data = value.get('chartData')
labels = {}
for opt in value.get('penOptions') or []:
	try:
		labels[str(opt['value'])] = str(opt['label'])
	except:
		pass
series = []
if data is None:
	return series
try:
	row_count = data.getRowCount()
except:
	row_count = 0
if row_count <= 0:
	return series
try:
	col_names = shared.TrendContext.columns(data)
except:
	try:
		col_names = [data.getColumnName(i) for i in range(data.getColumnCount())]
	except:
		return series

def add_series(name, column):
	if column not in col_names or column == 't_stamp':
		return
	try:
		filtered = shared.TrendContext.points(data, column)
	except:
		return
	series.append({'name': name or column, 'data': filtered})

used = set()
if isinstance(selected, (str, unicode)):
	selected = [selected] if selected else []
for item in selected or []:
	path = str(item or '')
	leaf = path.rsplit('/', 1)[-1]
	parts = path.split('/')
	if len(parts) >= 3 and leaf.upper() == 'VALUE' and parts[-2].upper() == 'VALUE':
		alias = parts[-3]
	else:
		alias = parts[-2] if len(parts) >= 2 and leaf.upper() == 'VALUE' else ((parts[-2] + ' ' + leaf) if len(parts) >= 2 else leaf)  # pax-bindings
	col = None
	if alias and alias in col_names:
		col = alias
	elif path and path in col_names:
		col = path
	else:
		for n in col_names:
			if n == 't_stamp':
				continue
			if n == leaf or n.endswith('/' + leaf) or n == alias or n.endswith('/' + alias):
				col = n
				break
	if col and col not in used:
		add_series(labels.get(path) or alias or col, col)
		used.add(col)
if not series:
	for column in col_names:
		if column != 't_stamp':
			add_series(column, column)
return series

